package server

const backupsHTML = `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width"><script src="/static/theme.js?v=electric-1"></script><link rel="stylesheet" href="/static/app.css?v=electric-1"><title>Backups · Kinosail Subtitles</title></head><body class="settings-page"><main class="settings-shell"><a class="back" href="/settings">{{icon "back"}} Settings</a><header class="settings-intro"><span class="eyebrow">Recovery</span><h1>Automatic backups</h1><p>Backups contain your Server settings, accounts, and activity. Media files and cached data are not included.</p></header><section><h2>Status</h2><p>{{if .Enabled}}Enabled{{else}}Not configured{{end}} · <a class="mode" href="/settings/configuration#backup.key">Deployment configuration</a></p>{{if .Encrypted}}<p>Encryption is on.</p>{{else}}<p>Backups need setup.</p>{{end}}<p>Destination: <code>{{.Directory}}</code></p><p>Schedule: {{.Interval}} · Keep {{.Retention}}</p><p>Latest: {{if .Latest}}{{.Latest}}{{else}}None{{end}}</p><p>Last successful backup: {{if .LastSuccess}}{{.LastSuccess}}{{else}}None{{end}}</p><p>Last verified: {{if .LastVerified}}{{.LastVerified}}{{else}}Never{{end}}</p>{{if .LastError}}<p>Last error: {{.LastError}}</p>{{end}}</section><section><h2>Actions</h2><form action="/settings/encrypted-backup" method="post"><button {{if not .Enabled}}disabled{{end}}>Back up now</button></form><form action="/settings/backups/verify" method="post"><button {{if not .Latest}}disabled{{end}}>Verify latest backup</button></form><p><a class="mode" href="/settings/backup">Download Server backup</a></p></section><section><h2>Disaster recovery</h2><p>Secrets are hidden and included only in encrypted recovery backups.</p></section></main></body></html>`

